    memcpy(key.data, &randomKey, sizeof(int)); // Storing the random key
    key.size = sizeof(int);

    value.data = malloc(sizeof(double)); // Allocating memory for value data
    if (!value.data) gf_bail(); // Check for successful memory allocation
    memcpy(value.data, &randomValue, sizeof(double)); // Storing the random value
    value.size = sizeof(double);

    rc = iwkv_cursor_set($cur, &value, 0);
    if (rc) gf_bail(); // Check if cursor set operation succeeded

    // Closing the cursor
    iwkv_cursor_close(&$cur);

    // Free allocated memory
    free(key.data);
    free(value.data);
}

